// agentpager-antigravity v4
// AgentPager (Antigravity) bridge hook runner
// Managed by AgentPager (Antigravity) - do not edit this file manually.
// Forwards Antigravity lifecycle hooks to AgentPager Bridge on 127.0.0.1:49361.
//
// v4 与 v3 的唯一区别：**Stop 也问桥要排队（pull 模型）**——脚本在 Stop 时把连接多留
// 一会儿，等桥回一行（有排队就回 `{"decision":"block","reason":"<排队文本>"}`，
// 无货回空行），原样打印出去。agy 把 block+reason 当 SYSTEM_MESSAGE 在同一进程内续跑
// （探针实证：事中 enqueue → 跑完 remove 级语义；连续 block 10 次后 agy 自己收场）。
// 于是排队投递不再起新 `agy.exe` 子进程：无进程锁、不烧第二份环境、终端天然可见。
// v3 的 Stop 是发完就扔（桥回包直接忽略），所以只有 v4 脚本才走 pull——版本门由信封里的
// `pullPrompt` 标记承担，桥只给带标记的 Stop 回排队。
// v2 的教训保持：非提问的 PreToolUse 一律立刻 allow（下面那条红线不动）。

const net = require("node:net");

const HOST = "127.0.0.1";
const PORT = 49361;
const CONNECT_TIMEOUT_MS = 500;

// 等手机作答的上限（挂钩超时是 720 秒，这里留出余量自己先收场）。
const DECISION_TIMEOUT_MS = 660_000;

// Stop pull 等桥回包的上限（hook 超时 30 秒内收场；本地回环毫秒级，4 秒只防桥卡死）。
const PULL_TIMEOUT_MS = 4000;

// stdin 迟迟不结束也不能把 agy 吊着：读不到工具名就按放行处理。
const STDIN_TIMEOUT_MS = 400;

const eventName = process.argv[2] || "Unknown";

let decided = false;
function decide(payload) {
  if (decided) return false;
  decided = true;
  try {
    process.stdout.write(JSON.stringify(payload) + "\n");
  } catch {
    // 忽略输出异常
  }
  return true;
}

// 已经写过 stdout 之后的收场：**不要立刻 exit**——管道 stdout 是异步的，直接退出会截断输出
// （Claude 那份脚本踩过同样的坑）。让进程自然退出，只留一个 unref 的兜底定时器防漏网 handle。
function exitSoon() {
  const fallback = setTimeout(() => process.exit(0), 1000);
  if (fallback.unref) fallback.unref();
}

// 非 PreToolUse 且非 Stop 的契约是空对象；PreToolUse 的默认是放行；
// Stop 走 pull（下面），三者都能"立刻收场、不留悬念"。
if (eventName !== "PreToolUse" && eventName !== "Stop") decide({});

const stdinGuard = setTimeout(() => {
  // Stop 的 stdin 不来就当空载荷直接问桥（拿不到 conversationId 会拿空回包，安全）。
  if (eventName === "Stop") onPayload({});
  else if (decide({ decision: "allow" })) exitSoon();
}, STDIN_TIMEOUT_MS);
if (stdinGuard.unref) stdinGuard.unref();

let input = "";
process.stdin.setEncoding("utf8");

process.stdin.on("data", chunk => {
  input += chunk;
});

process.stdin.on("end", () => {
  clearTimeout(stdinGuard);
  let data = {};
  if (input.trim()) {
    try {
      data = JSON.parse(input);
    } catch {
      data = {};
    }
  }
  onPayload(data);
});

process.stdin.on("error", () => {
  decide({ decision: "allow" });
  process.exit(0);
});

function buildEnvelope(data) {
  return {
    hook_source: "antigravity",
    payload: {
      event: eventName,
      conversationId: data.conversationId,
      workspacePaths: data.workspacePaths,
      transcriptPath: data.transcriptPath,
      artifactDirectoryPath: data.artifactDirectoryPath,
      modelName: data.modelName,
      toolCall: data.toolCall,
      terminationReason: data.terminationReason,
      error: data.error,
      // pull 版本门：只有 v4 脚本带它，桥只给带标记的 Stop 回排队。
      pullPrompt: eventName === "Stop",
    }
  };
}

// Stop-pull 交接（v4）：问桥要排队，有货桥回 block+reason（原样打印），
// 无货/超时/桥不在线一律打印 {}。单入守卫：stdin 结束与 stdinGuard 可能各调一次，
// 重复问桥会导致同一条排队被交接两次——第二次拿空回包才安全，所以这里必须拦一道。
let stopPulled = false;
function pullOnStop(data) {
  if (stopPulled) return;
  stopPulled = true;
  const envelope = buildEnvelope(data);
  const client = net.createConnection({ host: HOST, port: PORT });
  client.setTimeout(CONNECT_TIMEOUT_MS);

  const finish = (text) => {
    // 幂等：自收定时器与 close/error 回调可能同时开火，agy 只认第一行，多打一行就是事故。
    if (answered) return;
    answered = true;
    clearTimeout(pullTimer);
    try {
      const line = (text || "").trim();
      process.stdout.write((line.length > 0 ? line : "{}") + "\n");
    } catch {
      // 忽略输出异常
    }
    try { client.destroy(); } catch {
      // 忽略
    }
    exitSoon();
  };

  const pullTimer = setTimeout(() => finish(""), PULL_TIMEOUT_MS);
  if (pullTimer.unref) pullTimer.unref();

  let buf = "";
  let answered = false;
  client.on("connect", () => {
    // 回包窗口内不设连接超时，总控只认 pullTimer。
    client.setTimeout(0);
    try {
      client.write(JSON.stringify(envelope) + "\n");
    } catch {
      finish("");
    }
  });
  client.on("data", (chunk) => {
    if (answered) return;
    buf += chunk.toString("utf8");
    const index = buf.indexOf("\n");
    if (index < 0) return;
    finish(buf.slice(0, index));
  });
  const failOpen = () => {
    finish("");
  };
  client.on("timeout", () => {
    try { client.destroy(); } catch {
      // 忽略
    }
    failOpen();
  });
  client.on("error", () => {
    // Fail-Open：Bridge 未启动 / 连不上时 {} 干净结束，绝不阻断 Antigravity。
    try { client.destroy(); } catch {
      // 忽略
    }
    failOpen();
  });
  client.on("close", () => failOpen());
}

function onPayload(data) {
  const toolName = data && data.toolCall ? data.toolCall.name : null;
  const isQuestion = eventName === "PreToolUse" &&
    typeof toolName === "string" &&
    toolName.toLowerCase() === "ask_question";

  // Stop 走 pull，不进 forward（forward 等的是提问作答，Stop 用不上，问了也白问）。
  if (eventName === "Stop") {
    pullOnStop(data);
    return;
  }

  // 门禁红线：提问以外的 PreToolUse 必须立刻显式放行，绝不卡死 agy 循环。
  if (eventName === "PreToolUse" && !isQuestion) decide({ decision: "allow" });

  forward(data, isQuestion);
}

function forward(data, waitForDecision) {
  const envelope = buildEnvelope(data);
  const client = net.createConnection({ host: HOST, port: PORT });
  client.setTimeout(CONNECT_TIMEOUT_MS);

  // 等作答期间不再套用连接超时（那是给"连不上"用的，不是给"连上了在等"用的）。
  let decisionTimer = null;
  let received = false;

  client.on("connect", () => {
    client.setTimeout(waitForDecision ? 0 : CONNECT_TIMEOUT_MS);
    if (waitForDecision) {
      // 兜底：真等到超时也不能把 agy 挂死——放行，让终端自己的弹框接手。
      decisionTimer = setTimeout(() => {
        decide({ decision: "allow" });
        finish();
      }, DECISION_TIMEOUT_MS);
      if (decisionTimer.unref) decisionTimer.unref();
    }
    try {
      client.write(JSON.stringify(envelope) + "\n");
    } catch {
      client.destroy();
      process.exit(0);
    }
  });

  client.on("data", chunk => {
    if (!waitForDecision) {
      client.end();
      return;
    }
    if (received) return;
    received = true;
    if (decisionTimer) clearTimeout(decisionTimer);
    // Bridge 的回包就是决策本体，原样转给 agy（它认 decision/reason 这几个字段）。
    const text = chunk.toString("utf8").trim();
    if (text.length > 0) {
      if (!decided) {
        decided = true;
        try {
          process.stdout.write(text + "\n");
        } catch {
          // 忽略输出异常
        }
      }
    } else {
      // 空回包 = Bridge 主动撤了这条等待（等待已在别处结束）：放行，别干预。
      decide({ decision: "allow" });
    }
    finish();
  });

  client.on("timeout", () => {
    client.destroy();
    decide({ decision: "allow" });
    exitSoon();
  });

  client.on("error", () => {
    // Fail-Open：Bridge 未启动 / 连不上时静默放行，绝不阻断 Antigravity（终端弹框照旧）。
    client.destroy();
    decide({ decision: "allow" });
    exitSoon();
  });

  client.on("close", () => {
    if (decisionTimer) clearTimeout(decisionTimer);
    // 连接被对端关掉而没给决策（Bridge 撤等待）：放行。已给过决策的走自然退出。
    decide({ decision: "allow" });
    exitSoon();
  });

  function finish() {
    try {
      client.end();
    } catch {
      // 忽略
    }
    exitSoon();
  }
}
